package com.example.shortener.url;
import org.junit.jupiter.api.Test; import java.time.Instant; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.TestPropertySource; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @TestPropertySource(properties={"spring.datasource.url=jdbc:h2:mem:testdb;DB_CLOSE_DELAY=-1","app.short-url-base=http://localhost:8080/r/"}) class UrlShortenerServiceTest { @Autowired UrlShortenerService service; @Test void shortensAndPersistsUrl(){var r=service.shorten("https://example.com/a?b=1");assertNotNull(r.code());assertEquals("https://example.com/a?b=1",r.originalUrl());assertEquals(r.code(),service.find(r.code()).getCode());} @Test void rejectsJavascriptUrl(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.shorten("javascript:alert(1)"));} @Test void expiredLinksReturnGoneAndExposeExpiredStatus() throws Exception {var r=service.shorten("https://expired.example", Instant.now().plusMillis(20));Thread.sleep(40);var ex=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.resolve(r.code()));assertEquals(org.springframework.http.HttpStatus.GONE,ex.getStatusCode());assertEquals(ShortUrlStatus.EXPIRED,service.find(r.code()).getStatus());}
 @Test void rejectsExpiryInPast(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.shorten("https://example.com",Instant.now().minusSeconds(1)));}
 @Test void generatedCodesAreUnique(){var a=service.shorten("https://a.example");var b=service.shorten("https://b.example");assertNotEquals(a.code(),b.code());}}
